class Solution:
    def justify(self, words: List[str], width: int) -> List[str]:
        out, i, n = [], 0, len(words)
        while i < n:
            j, size = i + 1, len(words[i])
            while j < n and size + 1 + len(words[j]) <= width:
                size += 1 + len(words[j])
                j += 1
            gaps = j - i - 1
            if j == n or gaps == 0:
                line = " ".join(words[i:j])
                out.append(line + " " * (width - len(line)))
            else:
                q, r = divmod(width - (size - gaps), gaps)
                parts = [words[k] + " " * (q + (1 if k - i < r else 0)) for k in range(i, j - 1)]
                out.append("".join(parts) + words[j - 1])
            i = j
        return out

