class Solution {
    public List<String> justify(String[] words, int width) {
        List<String> out = new ArrayList<>();
        int i = 0, n = words.length;
        while (i < n) {
            int j = i + 1, size = words[i].length();
            while (j < n && size + 1 + words[j].length() <= width) size += 1 + words[j++].length();
            int gaps = j - i - 1;
            StringBuilder line = new StringBuilder();
            if (j == n || gaps == 0) {
                for (int k = i; k < j; k++) line.append(k > i ? " " : "").append(words[k]);
                while (line.length() < width) line.append(' ');
            } else {
                int spare = width - (size - gaps), q = spare / gaps, r = spare % gaps;
                for (int k = i; k < j - 1; k++) line.append(words[k]).append(" ".repeat(q + (k - i < r ? 1 : 0)));
                line.append(words[j - 1]);
            }
            out.add(line.toString());
            i = j;
        }
        return out;
    }
}

