class Solution {
public:
    vector<string> justify(vector<string>& words, int width) {
        vector<string> out;
        int i = 0, n = words.size();
        while (i < n) {
            int j = i + 1, size = words[i].size();
            while (j < n && size + 1 + (int) words[j].size() <= width) size += 1 + words[j++].size();
            int gaps = j - i - 1;
            string line;
            if (j == n || gaps == 0) {
                for (int k = i; k < j; k++) line += (k > i ? " " : "") + words[k];
                line.resize(width, ' ');
            } else {
                int spare = width - (size - gaps), q = spare / gaps, r = spare % gaps;
                for (int k = i; k < j - 1; k++) line += words[k] + string(q + (k - i < r ? 1 : 0), ' ');
                line += words[j - 1];
            }
            out.push_back(line);
            i = j;
        }
        return out;
    }
};

