char** justify(char** words, int wordsSize, int width, int* returnSize) {
    char** out = malloc(wordsSize * sizeof(char*));
    int count = 0, i = 0, n = wordsSize;
    while (i < n) {
        int j = i + 1, size = strlen(words[i]);
        while (j < n && size + 1 + (int) strlen(words[j]) <= width) size += 1 + strlen(words[j++]);
        int gaps = j - i - 1, pos = 0;
        char* line = malloc(width + 1);
        if (j == n || gaps == 0) {
            for (int k = i; k < j; k++) {
                if (k > i) line[pos++] = ' ';
                int len = strlen(words[k]);
                memcpy(line + pos, words[k], len);
                pos += len;
            }
            while (pos < width) line[pos++] = ' ';
        } else {
            int spare = width - (size - gaps), q = spare / gaps, r = spare % gaps;
            for (int k = i; k < j; k++) {
                int len = strlen(words[k]);
                memcpy(line + pos, words[k], len);
                pos += len;
                if (k < j - 1) for (int t = q + (k - i < r ? 1 : 0); t > 0; t--) line[pos++] = ' ';
            }
        }
        line[pos] = '\0';
        out[count++] = line;
        i = j;
    }
    *returnSize = count;
    return out;
}
